from itertools import permutations
from typing import List

class Solution:
    def minimumTime(self, n: int, start: int, requests: List[List[int]]) -> int:
        need = {}
        for a, f in requests:
            need[f] = max(need.get(f, 0), a)
        floors = list(need.keys())
        best = float('inf')
        for perm in permutations(floors):
            t, cur = 0, start
            for f in perm:
                t = max(t + abs(cur - f), need[f])
                cur = f
            best = min(best, t)
        return best

