import java.util.*;

class Solution {
    public long minimumTime(int n, int start, int[][] requests) {
        TreeMap<Integer, Long> need = new TreeMap<>();
        for (int[] r : requests) need.merge(r[1], (long) r[0], Math::max);
        int[] fl = need.keySet().stream().mapToInt(Integer::intValue).toArray();
        long[] arr = new long[fl.length];
        for (int i = 0; i < fl.length; i++) arr[i] = need.get(fl[i]);
        Integer[] ord = new Integer[fl.length];
        for (int i = 0; i < ord.length; i++) ord[i] = i;
        long best = Long.MAX_VALUE;
        boolean first = true;
        Arrays.sort(ord);
        while (first || nextPerm(ord)) {
            first = false;
            long t = 0; int cur = start;
            for (int idx : ord) {
                t = Math.max(t + Math.abs(fl[idx] - cur), arr[idx]);
                cur = fl[idx];
            }
            best = Math.min(best, t);
        }
        return best;
    }
    private boolean nextPerm(Integer[] a) {
        int i = a.length - 2;
        while (i >= 0 && a[i] >= a[i + 1]) i--;
        if (i < 0) return false;
        int j = a.length - 1;
        while (a[j] <= a[i]) j--;
        int tmp = a[i]; a[i] = a[j]; a[j] = tmp;
        for (int l = i + 1, r = a.length - 1; l < r; l++, r--) {
            tmp = a[l]; a[l] = a[r]; a[r] = tmp;
        }
        return true;
    }
}

