    for (const [a, f] of requests) need.set(f, Math.max(need.get(f) ?? 0, a));
    const floors = [...need.keys()], m = floors.length;
    let best = Infinity;
    const perm = (k, used, order) => {
        if (k === m) {
            let t = 0, cur = start;
            for (const f of order) {
                t = Math.max(t + Math.abs(cur - f), need.get(f));
                cur = f;
            }
            best = Math.min(best, t);
            return;
        }
        for (let i = 0; i < m; i++) if (!used[i]) {
            used[i] = true; order.push(floors[i]);
            perm(k + 1, used, order);
            order.pop(); used[i] = false;
        }
    };
    perm(0, new Array(m).fill(false), []);
    return best;
};

