from typing import List

class Solution:
    def minimumTime(self, n: int, start: int, requests: List[List[int]]) -> int:
        need = {start: 0}
        for a, f in requests:
            need[f] = max(need.get(f, 0), a)
        p = sorted(need)
        m = len(p)
        s = p.index(start)
        INF = float('inf')
        dp = [[[INF] * 2 for _ in range(m)] for _ in range(m)]
        dp[s][s][0] = dp[s][s][1] = 0
        for length in range(2, m + 1):
            for l in range(m - length + 1):
                r = l + length - 1
                dl = need[p[l]]
                dr = need[p[r]]
                c0 = INF
                v = dp[l + 1][r][0]
                if v < INF: c0 = min(c0, v + p[l + 1] - p[l])
                v = dp[l + 1][r][1]
                if v < INF: c0 = min(c0, v + p[r] - p[l])
                dp[l][r][0] = max(c0, dl)
                c1 = INF
                v = dp[l][r - 1][1]
                if v < INF: c1 = min(c1, v + p[r] - p[r - 1])
                v = dp[l][r - 1][0]
                if v < INF: c1 = min(c1, v + p[r] - p[l])
                dp[l][r][1] = max(c1, dr)
        return min(dp[0][m - 1][0], dp[0][m - 1][1])

