using namespace std;

class Solution {
public:
    long long minimumTime(int n, int start, vector<vector<int>>& requests) {
        map<int, long long> need;
        need[start] = 0;
        for (auto& r : requests) need[r[1]] = max(need[r[1]], (long long)r[0]);
        vector<int> p;
        for (auto& kv : need) p.push_back(kv.first);
        int m = p.size(), s = 0;
        while (p[s] != start) s++;
        const long long INF = LLONG_MAX / 4;
        vector<vector<array<long long,2>>> dp(m, vector<array<long long,2>>(m, {INF, INF}));
        dp[s][s][0] = dp[s][s][1] = 0;
        for (int len = 2; len <= m; len++) {
            for (int l = 0; l + len - 1 < m; l++) {
                int r = l + len - 1;
                long long c0 = INF, c1 = INF;
                auto& a = dp[l + 1][r];
                c0 = min(c0, min(a[0] + p[l + 1] - p[l], a[1] + p[r] - p[l]));
                dp[l][r][0] = max(c0, need[p[l]]);
                auto& b = dp[l][r - 1];
                c1 = min(c1, min(b[1] + p[r] - p[r - 1], b[0] + p[r] - p[l]));
                dp[l][r][1] = max(c1, need[p[r]]);
            }
        }
        return min(dp[0][m - 1][0], dp[0][m - 1][1]);
    }
};

