import java.util.*;

class Solution {
    public long minimumTime(int n, int start, int[][] requests) {
        TreeMap<Integer, Long> need = new TreeMap<>();
        need.put(start, 0L);
        for (int[] r : requests) need.merge(r[1], (long) r[0], Math::max);
        int m = need.size();
        int[] p = new int[m];
        long[][] req = new long[m][2];
        int i = 0, s = 0;
        for (Map.Entry<Integer, Long> e : need.entrySet()) {
            p[i] = e.getKey();
            if (p[i] == start) s = i;
            req[i][0] = e.getValue();
            i++;
        }
        long INF = Long.MAX_VALUE / 4;
        long[][][] dp = new long[m][m][2];
        for (long[][] row : dp) for (long[] cell : row) { cell[0] = INF; cell[1] = INF; }
        dp[s][s][0] = dp[s][s][1] = 0;
        for (int len = 2; len <= m; len++) {
            for (int l = 0; l + len - 1 < m; l++) {
                int r = l + len - 1;
                long c0 = Math.min(dp[l + 1][r][0] + p[l + 1] - p[l], dp[l + 1][r][1] + p[r] - p[l]);
                dp[l][r][0] = Math.max(c0, req[l][0]);
                long c1 = Math.min(dp[l][r - 1][1] + p[r] - p[r - 1], dp[l][r - 1][0] + p[r] - p[l]);
                dp[l][r][1] = Math.max(c1, req[r][0]);
            }
        }
        return Math.min(dp[0][m - 1][0], dp[0][m - 1][1]);
    }
}

